#include <iostream>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    cin >> n >> t;

    // dp[last height][direction: 0 = down, 1 = up][peaks][valleys]
    unsigned long long dp[5][2][11][11] = {};

    for (int first = 1; first <= 4; ++first) {
        for (int second = 1; second <= 4; ++second) {
            if (first == second) continue;
            int direction = (second > first);
            dp[second][direction][0][0]++;
        }
    }

    for (int position = 3; position <= n; ++position) {
        unsigned long long next[5][2][11][11] = {};

        for (int last = 1; last <= 4; ++last) {
            for (int oldDirection = 0; oldDirection <= 1; ++oldDirection) {
                for (int peaks = 0; peaks <= t; ++peaks) {
                    for (int valleys = 0; valleys <= t - 1; ++valleys) {
                        auto ways = dp[last][oldDirection][peaks][valleys];
                        if (ways == 0) continue;

                        for (int current = 1; current <= 4; ++current) {
                            if (current == last) continue;

                            int newDirection = (current > last);
                            int newPeaks = peaks;
                            int newValleys = valleys;

                            if (oldDirection == 1 && newDirection == 0)
                                ++newPeaks;
                            else if (oldDirection == 0 && newDirection == 1)
                                ++newValleys;

                            if (newPeaks <= t && newValleys <= t - 1) {
                                next[current][newDirection][newPeaks][newValleys] += ways;
                            }
                        }
                    }
                }
            }
        }

        for (int h = 1; h <= 4; ++h)
            for (int d = 0; d < 2; ++d)
                for (int p = 0; p <= t; ++p)
                    for (int v = 0; v <= t - 1; ++v)
                        dp[h][d][p][v] = next[h][d][p][v];
    }

    unsigned long long answer = 0;
    for (int height = 1; height <= 4; ++height)
        for (int direction = 0; direction <= 1; ++direction)
            answer += dp[height][direction][t][t - 1];

    cout << answer << '\n';
    return 0;
}

