                        if (!ways) continue;

                        for (int y = 0; y < 4; ++y) {
                            if (y == last) continue;

                            int newDir = (y > last ? 1 : 2);
                            int newPeaks = peaks;
                            int newValleys = valleys;

                            if (dir == 1 && newDir == 2) ++newPeaks;
                            if (dir == 2 && newDir == 1) ++newValleys;

                            if (newPeaks <= t && newValleys <= t) {
                                next[y][newDir][newPeaks][newValleys] += ways;
                            }
                        }
                    }
                }
            }
        }

        for (int y = 0; y < 4; ++y)
            for (int dir = 0; dir < 3; ++dir)
                for (int p = 0; p <= t; ++p)
