        for (int b = 1; b <= 4; ++b) {
            if (a != b) {
                int direction = (b > a) ? 1 : 0;
                dp[b][direction][0][0]++;
            }
        }
    }

    for (int pos = 3; pos <= n; ++pos) {
        for (int y = 1; y <= 4; ++y)
            for (int d = 0; d < 2; ++d)
                for (int peaks = 0; peaks <= 10; ++peaks)
                    for (int valleys = 0; valleys <= 10; ++valleys)
                        nextDp[y][d][peaks][valleys] = 0;

        for (int last = 1; last <= 4; ++last) {
            for (int oldDir = 0; oldDir < 2; ++oldDir) {
                for (int peaks = 0; peaks <= t; ++peaks) {
                    for (int valleys = 0; valleys <= t - 1; ++valleys) {
                        auto ways = dp[last][oldDir][peaks][valleys];
                        if (ways == 0) continue;

                        for (int current = 1; current <= 4; ++current) {
                            if (current == last) continue;

                            int newDir = (current > last) ? 1 : 0;
                            int newPeaks = peaks + (oldDir == 1 && newDir == 0);
                            int newValleys = valleys + (oldDir == 0 && newDir == 1);

                            if (newPeaks <= t && newValleys <= t - 1)
                                nextDp[current][newDir][newPeaks][newValleys] += ways;
                        }
                    }
                }
            }
        }

        for (int y = 1; y <= 4; ++y)
            for (int d = 0; d < 2; ++d)
                for (int peaks = 0; peaks <= 10; ++peaks)
                    for (int valleys = 0; valleys <= 10; ++valleys)
                        dp[y][d][peaks][valleys] = nextDp[y][d][peaks][valleys];
    }

    unsigned long long answer = 0;
    for (int y = 1; y <= 4; ++y)
        for (int d = 0; d < 2; ++d)
            answer += dp[y][d][t][t - 1];

    cout << answer << '\n';
    return 0;
}

